const T0 = "2026-01-05T09:00:00.000Z";

type SeedItem = Omit<Item, "org_id" | "created_at" | "updated_at" | "created_by" | "status" | "visibility" | "embargo_until"> &
  Partial<Pick<Item, "status" | "visibility" | "embargo_until" | "created_at">>;

const base = (i: SeedItem): Item => ({
  status: "published",
  visibility: "public",
  embargo_until: null,
  created_at: T0,
  ...i,
  org_id: ORG_ID,
  created_by: null,
  updated_at: i.created_at ?? T0,
});

