/** Deterministic chunk IDs: item order × page. */
export function chunkId(itemId: string, page: number) {
  const n = Number(itemId.slice(-4));
  return sid(10000 + n * 10 + page);
}

// ------------------------------------------------------------ synthetic CSVs
function lcg(seed: number) {
  let s = seed;
  return () => {
    s = (s * 1664525 + 1013904223) % 4294967296;
    return s / 4294967296;
  };
}

/** Synthetic daily air temperature (°C) — clearly fake, deterministic. */
export function awsCsv(): string {
  const rnd = lcg(46);
  const rows = ["date,air_temp_c,wind_speed_ms,relative_humidity_pct"];
  const start = Date.UTC(2026, 0, 1);
  for (let d = 0; d < 59; d++) {
    const date = new Date(start + d * 86400000).toISOString().slice(0, 10);
    const t = (-3 + 4 * Math.sin((d / 59) * Math.PI) - d * 0.06 + (rnd() - 0.5) * 3).toFixed(1);
    const w = (4 + rnd() * 9).toFixed(1);
    const rh = d % 17 === 5 ? "" : String(Math.round(55 + rnd() * 30));
    rows.push(`${date},${t},${w},${rh}`);
  }
  return rows.join("\n") + "\n";
}

/** Synthetic monthly sea-ice index (unitless) — clearly fake, deterministic. */
export function seaIceCsv(): string {
  const rnd = lcg(2020);
  const rows = ["month,sea_ice_index,anomaly_index"];
  for (let y = 2020; y <= 2025; y++) {
    for (let m = 1; m <= 12; m++) {
      const season = Math.cos(((m - 9) / 12) * 2 * Math.PI);
      const v = 50 + 35 * season + (rnd() - 0.5) * 6;
      rows.push(`${y}-${String(m).padStart(2, "0")},${v.toFixed(2)},${((rnd() - 0.5) * 4).toFixed(2)}`);
    }
  }
  return rows.join("\n") + "\n";
}

export const datasetCsv: Record<string, { csv: () => string; units: Record<string, string> }> = {
  [ITEM.dAws]: { csv: awsCsv, units: { air_temp_c: "°C", wind_speed_ms: "m/s", relative_humidity_pct: "%" } },
  [ITEM.dIce]: { csv: seaIceCsv, units: { sea_ice_index: "index (unitless)", anomaly_index: "index (unitless)" } },
};

